        let error = registry
            .validate_provided(&LINE_A, &provided, &cmd)
            .expect_err("LineB's flag must be rejected for LineA");
        assert!(matches!(error, CliError::UnconsumedFlag { .. }));
        assert_eq!(error.to_string(), "--line-b-flag is not used by LineA");
    }

    #[test]
