    }

    #[test]
    #[should_panic(expected = "consumes unknown SharedArgs flag id \"not_a_shared_arg\"")]
    fn registry_rejects_unknown_consumed_shared_arg() {
        let _ = ModelLineRegistry::new(vec![&LINE_UNKNOWN_SHARED]);
