444	        let reason = MODEL_LINE.probe(&json).unwrap_err();
445	        assert!(reason.contains("qwen3"), "{reason}");
446	    }
447	
448	    #[test]
449	    fn accepts_graph_png_dump() {
450	        validate_argv(&["pegainfer", "--dump-graph-png", "decode.png"])
451	            .expect("graph PNG dump with CUDA Graph enabled should validate");
452	    }
