132	impl ModelLine for Qwen3Line {
133	    fn name(&self) -> &'static str {
134	        "Qwen3"
135	    }
136	
137	    fn probe(&self, config: &serde_json::Value) -> Result<(), String> {
138	        let model_type = config.get("model_type").and_then(serde_json::Value::as_str);
139	        if model_type != Some("qwen3") {
140	            return Err(format!("model_type {model_type:?} is not \"qwen3\""));
141	        }
142	        crate::probe_config_json(config).map_err(|error| error.to_string())
143	    }
144	
145	    fn augment_cli(&self, cmd: clap::Command) -> clap::Command {
146	        Qwen3Cli::augment_args(cmd)
147	    }
148	
149	    fn consumed_shared_args(&self) -> &'static [&'static str] {
150	        &[
151	            "cuda_graph",
152	            "dump_graph_png",
153	            "device_ordinal",
154	            "tp_size",
155	            "kv_offload",
156	            "kv_offload_host_gib",
157	            "kv_offload_hugepages",
158	            "kv_p2p_metaserver_addr",
159	            "kv_p2p_advertise_addr",
160	            "kv_p2p_nics",
161	            "no_prefix_cache",
162	            "max_prefill_tokens",
163	            "dflash_draft_model_path",
164	            "decode_overlap",
165	            "decode_sm_pct",
166	        ]
167	    }
168	
169	    fn arg_requirements(&self) -> &'static [ArgRequirement] {
170	        &[
171	            ("kv_p2p_flush_on_finish", &["kv_p2p_metaserver_addr"]),
172	            (
173	                "kv_pd_vllm_seed",
174	                &["kv_p2p_metaserver_addr", "kv_pd_vllm_namespace"],
175	            ),
176	            ("kv_pd_vllm_namespace", &["kv_pd_vllm_seed"]),
177	            ("kv_pd_miss_wait_ms", &["kv_pd_vllm_seed"]),
178	        ]
179	    }
180	
181	    fn validate(
182	        &self,
183	        ctx: &LaunchContext<'_>,
184	        provided: &BTreeSet<String>,
185	    ) -> Result<(), CliError> {
186	        let cli = cli(ctx);
187	        let shared = ctx.shared;
188	        if !cli.enable_lora && !cli.lora_modules.is_empty() {
189	            return Err(CliError::rule("--lora-modules requires --enable-lora"));
190	        }
191	        if !cli.enable_lora
192	            && (provided.contains("max_loras") || provided.contains("max_lora_rank"))
193	        {
194	            return Err(CliError::rule(
195	                "--max-loras and --max-lora-rank require --enable-lora",
196	            ));
197	        }
198	        if shared.dump_graph_png.is_some() && cli.enable_lora {
199	            return Err(CliError::rule(
200	                "--dump-graph-png is not supported with --enable-lora (LoRA disables CUDA Graph)",
201	            ));
202	        }
203	        if shared.decode_overlap != CliDecodeOverlap::Off && shared.tp_size > 1 {
204	            return Err(CliError::rule(
205	                "--decode-overlap is single-GPU only; tp_size>1 has no prefill/decode overlap",
206	            ));
207	        }
208	        if cli.batch_invariant {
209	            if cli.enable_lora {
210	                return Err(CliError::rule(
211	                    "--batch-invariant is not supported with --enable-lora; enable one at a time",
212	                ));
213	            }
214	            if shared.decode_overlap != CliDecodeOverlap::Off {
215	                return Err(CliError::rule(
216	                    "--batch-invariant is not compatible with --decode-overlap; the stream override would force the pinned GEMM to bail at runtime",
217	                ));
218	            }
219	            if shared.kv_offload {
220	                return Err(CliError::rule(
221	                    "--batch-invariant is not supported with --kv-offload: offload keeps prefix matching \
222	                     on (--no-prefix-cache only disables HBM retention there), and a host-tier prefix hit \
223	                     shifts a prompt's chunk boundaries off the request-local grid",
224	                ));
225	            }
226	            if shared.dflash_draft_model_path.is_some() {
227	                return Err(CliError::rule(
228	                    "--batch-invariant is not supported with DFlash speculative decoding; enable one at a time",
229	                ));
230	            }
231	            if shared.tp_size > 1 {
232	                return Err(CliError::rule(
233	                    "--batch-invariant is not supported with --tp-size > 1; enable one at a time",
234	                ));
235	            }
236	            if !shared.no_prefix_cache {
237	                return Err(CliError::rule(
238	                    "--batch-invariant requires --no-prefix-cache; prefix-cache hits move a prompt's chunk \
239	                     boundaries off the request-local grid, so batch-invariant prefill cannot be provided",
240	                ));
241	            }
242	        }
243	        if shared.dflash_draft_model_path.is_some() {
244	            if cli.enable_lora {
245	                return Err(CliError::rule(
246	                    "--dflash-draft-model-path is not supported with --enable-lora",
247	                ));
248	            }
249	            if shared.kv_offload {
250	                return Err(CliError::rule(
251	                    "--dflash-draft-model-path is not supported with --kv-offload",
252	                ));
253	            }
254	            if shared.tp_size != 1 {
255	                return Err(CliError::rule(
256	                    "--dflash-draft-model-path currently requires --tp-size=1",
257	                ));
258	            }
259	        }
260	        if cli.eagle3_draft_model_path.is_some() {
261	            let conflicts = [
262	                (
263	                    shared.dflash_draft_model_path.is_some(),
264	                    "--dflash-draft-model-path",
265	                ),
266	                (cli.enable_lora, "--enable-lora"),
267	                (shared.kv_offload, "--kv-offload"),
268	                (
269	                    shared.decode_overlap != CliDecodeOverlap::Off,
270	                    "--decode-overlap",
271	                ),
272	                (cli.batch_invariant, "--batch-invariant"),
273	            ];
274	            if let Some((_, flag)) = conflicts.iter().find(|(set, _)| *set) {
275	                return Err(CliError::rule(format!(
276	                    "--eagle3-draft-model-path is not supported with {flag}"
277	                )));
278	            }
279	            if shared.tp_size != 1 {
280	                return Err(CliError::rule(
281	                    "--eagle3-draft-model-path currently requires --tp-size=1",
282	                ));
283	            }
284	        }
285	        Ok(())
286	    }
287	
288	    fn serve_plan(&self, ctx: &LaunchContext<'_>) -> Result<ServePlan, CliError> {
289	        let cli = cli(ctx);
290	        Ok(ServePlan {
291	            lora_modules: cli.enable_lora.then(|| cli.lora_modules.clone()),
292	            ..ServePlan::default()
293	        })
294	    }
295	
296	    fn launch(&self, ctx: &LaunchContext<'_>) -> anyhow::Result<LaunchedEngine> {
297	        let cli = cli(ctx);
298	        let shared = ctx.shared;
299	        let offload = if shared.kv_offload {
300	            let bytes = (shared.kv_offload_host_gib * f64::from(1u32 << 30)) as usize;
301	            let mut offload = Qwen3OffloadOptions::enabled(bytes);
302	            offload.use_hugepages = shared.kv_offload_hugepages;
303	            if let (Some(metaserver_addr), Some(advertise_addr)) = (
304	                shared.kv_p2p_metaserver_addr.clone(),
305	                shared.kv_p2p_advertise_addr.clone(),
306	            ) {
307	                offload = offload.with_p2p(Qwen3P2pOptions {
308	                    metaserver_addr,
309	                    advertise_addr,
310	                    rdma_nics: shared.kv_p2p_nics.clone(),
311	                    flush_on_finish: cli.kv_p2p_flush_on_finish,
312	                });
313	            }
314	            if let Some(seed) = cli.kv_pd_vllm_seed.clone() {
315	                offload = offload.with_vllm_compat(Qwen3VllmCompatOptions {
316	                    python_hash_seed: seed,
317	                    namespace: cli
318	                        .kv_pd_vllm_namespace
319	                        .clone()
320	                        .expect("clap requires kv_pd_vllm_namespace"),
321	                    miss_wait: std::time::Duration::from_millis(cli.kv_pd_miss_wait_ms),
322	                });
323	            }
324	            offload
325	        } else {
326	            Qwen3OffloadOptions::disabled()
327	        };
328	        let lora = cli.enable_lora.then_some(Qwen3LoraOptions {
329	            max_loras: cli.max_loras,
330	            max_lora_rank: cli.max_lora_rank,
331	        });
332	        let kv_cache_memory_margin_bytes = cli
333	            .kv_cache_memory_margin_mib
334	            .checked_mul(1 << 20)
335	            .ok_or_else(|| {
336	                anyhow::anyhow!(
337	                    "--kv-cache-memory-margin-mib is too large: {}",
338	                    cli.kv_cache_memory_margin_mib
339	                )
340	            })?;
341	        crate::launch(
342	            ctx.model_path,
343	            Qwen3LaunchOptions {
344	                device_ordinal: shared.device_ordinal,
345	                tp_size: shared.tp_size,
346	                cuda_graph: shared.cuda_graph,
347	                dump_graph_png: shared.dump_graph_png.clone(),
348	                offload,
349	                no_prefix_cache: shared.no_prefix_cache,
350	                max_prefill_tokens: shared
351	                    .max_prefill_tokens
352	                    .unwrap_or(crate::DEFAULT_MAX_PREFILL_TOKENS),
353	                memory: Qwen3MemoryOptions::new(
354	                    cli.gpu_memory_utilization,
355	                    kv_cache_memory_margin_bytes,
356	                    cli.kv_page_size,
357	                )
358	                .validate()?,
359	                lora,
360	                decode_overlap: resolve_decode_overlap(shared.decode_overlap, shared.decode_sm_pct),
361	                batch_invariant: cli.batch_invariant,
362	                dflash_draft_model_path: shared.dflash_draft_model_path.clone(),
363	                eagle3_draft_model_path: cli.eagle3_draft_model_path,
364	            },
365	        )
366	        .map(LaunchedEngine::Stepped)
367	    }
368	}
369	
370	fn parse_max_lora_rank_arg(value: &str) -> Result<usize, String> {
371	    let rank = value
372	        .parse::<usize>()
373	        .map_err(|error| format!("invalid --max-lora-rank: {error}"))?;
374	    if Qwen3LoraOptions::is_supported_max_lora_rank(rank) {
375	        Ok(rank)
376	    } else {
377	        Err(format!(
378	            "--max-lora-rank must be one of: {}",
379	            Qwen3LoraOptions::supported_max_lora_ranks_display()
380	        ))
381	    }
382	}
383	
384	/// PYTHONHASHSEED as vLLM accepts it: a decimal integer in [0, 4294967295].
385	/// An empty or malformed seed would derive a well-formed key space that can
386	/// never match the peer — a config error must fail here, not as slow requests.
387	fn parse_pythonhashseed(s: &str) -> Result<String, String> {
388	    if s.parse::<u32>().is_err() || s.starts_with('+') {
389	        return Err(format!(
390	            "PYTHONHASHSEED must be a decimal integer in [0, 4294967295], got {s:?}"
391	        ));
392	    }
393	    Ok(s.to_string())
394	}
395	
396	/// A pegaflow namespace digest: exactly 8 lowercase hex chars.
397	fn parse_pegaflow_namespace(s: &str) -> Result<String, String> {
398	    if s.len() != 8
399	        || !s
400	            .bytes()
401	            .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
402	    {
403	        return Err(format!(
404	            "namespace must be an 8-char lowercase hex digest, got {s:?}"
405	        ));
406	    }
407	    Ok(s.to_string())
408	}
